}

label {
    font-weight: 500;
    margin-bottom: 0.5rem;
    font-size: 0.875rem;
}

input {
    padding: 0.75rem 1rem;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    font-size: 1rem;
    transition: border-color 0.2s, box-shadow 0.2s;
    outline: none;
}

input:focus {
    border-color: var(--border-focus);
