AssistantMessageToolRequest(name='create', tool_call_id='function-call-d0f6e966-a5c5-451c-a43d-fb5de9ef4b00', arguments={'file_text': "document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('contactForm');
    const fullName = document.getElementById('fullName');
    const email = document.getElementById('email');
    const phone = document.getElementById('phone');
    const formStatus = document.getElementById('formStatus');

    const validators = {
        fullName: (val) => val.trim().length > 0,
        email: (val) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val),
        phone: (val) => {
            if (!val) return true; // Optional
            // Match (XXX) XXX-XXXX format
            return /^\(\d{3}\) \d{3}-\d{4}$/.test(val);
        }
    };

    const validateField = (input, validator, errorId) => {
        const isValid = validator(input.value);
        const errorElement = document.getElementById(errorId);

        if (isValid) {
            input.classList.remove('invalid');
            errorElement.style.display = 'none';
        } else {
            input.classList.add('invalid');
            errorElement.style.display = 'block';
        }
        return isValid;
    };

    // Real-time validation on input
    fullName.addEventListener('input', () => validateField(fullName, validators.fullName, 'fullNameError'));
    email.addEventListener('input', () => validateField(email, validators.email, 'emailError'));
    phone.addEventListener('input', () => validateField(phone, validators.phone, 'phoneError'));

    // Validation on blur
    fullName.addEventListener('blur', () => validateField(fullName, validators.fullName, 'fullNameError'));
    email.addEventListener('blur', () => validateField(email, validators.email, 'emailError'));
    phone.addEventListener('blur', () => validateField(phone, validators.phone, 'phoneError'));

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const isNameValid = validateField(fullName, validators.fullName, 'fullNameError');
        const isEmailValid = validateField(email, validators.email, 'emailError');
        const isPhoneValid = validateField(phone, validators.phone, 'phoneError');

        if (isNameValid && isEmailValid && isPhoneValid) {
            formStatus.textContent = 'Message sent successfully! We will contact you soon.';
            formStatus.className = 'form-status success';
            form.reset();

            // Remove validation classes after reset
            [fullName, email, phone].forEach(el => el.classList.remove('invalid'));

            // Hide status after 5 seconds
            setTimeout(() => {
                formStatus.style.display = 'none';
            }, 5000);
        } else {
            formStatus.textContent = 'Please fix the errors above before submitting.';
            formStatus.className = 'form-status error';
        }
    });
});
